# Explicitly include the descriptor/domain, observation and partitioner tests
# named by those requirements, in addition to the seam regressions above.
for group,extra in {
 'type-descriptors':['TestV2FoundationDescriptorImmutability','TestV2FoundationDescriptorValidation','TestV2FoundationProtocolTypeConversion'],
 'routing-tokens':['TestV2StreamingPartitioners','TestScyllaCDCPartitioner_HashInt64MatchesHash','TestScyllaCDCPartitioner_HashInt64_ShortKeyReturnsMinToken','TestScyllaCDCPartitioner_HashInt64_ZeroAlloc'],
 'observers-optional':['TestObserve','TestObserve_Pagination','TestBatchObserve','TestApplicationInformation','TestTracing','TestTracingNewAPI','TestTracerEnhanced','TestTracerEnhancedNotReady','TestTracerEnhancedErrors','TestTraceWriter','TestTraceWriterIncomplete','TestTraceWriterAttemptFloor','TestTraceWriterError','TestV2LifecyclePanicContained'],
 'protocol-limits':['TestV2ServerErrorsExposeTheirCodeThroughWrappers','TestParseErrorFrame','TestParseErrorFrameTruncated','TestReadErrorMapRejectsBadAddress','TestReadErrorMapNegativeCount','TestErrorsParse','TestQueryError_PotentiallyExecuted','TestQueryError_IsIdempotent','TestQueryError_Error','TestMalformedFrameErrorWraps'],
}.items():
    scope,pattern=GROUPS[group]
    GROUPS[group]=(scope,'(?:'+pattern+'|'+'|'.join(re.escape(x) for x in extra)+')')

def build():
    declarations=matrix.read(OUT/'current-declarations.json')
    commands={}
    for folder in ['checks','performance']:
        p=OUT/folder/'checks.json'
        for c in matrix.read(p) if p.exists() else []:commands[folder+'/'+c['name']]=c
    for path in OUT.glob('*.json'):
        r=matrix.read(path)
        if isinstance(r,dict) and r.get('source_sha256') and r.get('status')=='passed':
            for c in r.get('commands',[]):commands[path.stem+'/'+c['name']]=c
    outcomes={key:matrix.package_outcomes(c) for key,c in commands.items()}
    proofs={};groups={};missing=[]
    for group,(scope,pattern) in GROUPS.items():
        selected=[d for d in declarations if d['Kind']=='func' and d['Name'].startswith('Test') and not d['Receiver'] and re.fullmatch(pattern,d['Name'])]
        refs=[]
        for d in selected:
            identity=d['File']+'::'+d['Name'];refs.append(identity)
            package='github.com/scylladb/gocql/v2'+('/'+str(Path(d['File']).parent) if Path(d['File']).parent!=Path('.') else '')
            passed=[]
            for key,tests in outcomes.items():
                flat={n:a for (p,n),a in tests.items() if p==package}
                if matrix.effective(flat,d['Name']):passed.append(key)
            proofs[identity]=dict(file=d['File'],line=d['Line'],name=d['Name'],source_sha256=d['SHA'],complete_assertion_source=d['Source'],current_effective_passes=passed)
        absent=[p for p in refs if not proofs[p]['current_effective_passes']]
        if not selected:missing.append('empty explicit dossier '+group)
        groups[group]=dict(scope=scope,selection=pattern,tests=refs,missing_effective_passes=absent,status='open' if absent or not selected else 'current-assertions-passed')
    result=dict(runtime_source_sha256=matrix.sha(OUT/'checks/source.json'),groups=groups,assertions=proofs,commands=commands,missing=missing,scope='Dossiers are scoped current assertion/pass evidence, not a claim that any unreviewed requirement is achieved.')
    matrix.write(E/'step17-proof-catalog.json',result)
    print(json.dumps(dict(groups=len(groups),assertions=len(proofs),missing_groups=missing,unpassed=sum(len(g['missing_effective_passes']) for g in groups.values()))))
    return result
if __name__=='__main__':build()
